// The autonomy dial and the daily ceiling.
//
// ⛔ THE LOW-STAR RULE IS NOT REACHABLE FROM HERE. This route can set the mode
// to `autopilot` and the ceiling to a thousand, and a 1–2★ review still routes
// to the approval queue, because that branch runs before the mode is read
// (`agent/guardrails.ts`) and the database trigger refuses to let a low-star
// reply lose its approval flag. There is deliberately no field on this endpoint
// that touches it.

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/app/_lib/supabase/server";
import { adminSupabase } from "@/app/_lib/supabase/admin";
import { DEMO_READONLY_MESSAGE, isDemoEmail } from "@/app/_lib/demo";
import type { AutonomyMode } from "@/app/_lib/types";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const MODES: AutonomyMode[] = ["manual", "copilot", "autopilot"];

export async function POST(req: NextRequest) {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  if (isDemoEmail(user.email)) {
    return NextResponse.json({ error: DEMO_READONLY_MESSAGE }, { status: 403 });
  }

  const body = (await req.json().catch(() => ({}))) as {
    mode?: string;
    dailyAutoPostCap?: number;
  };

  const patch: Record<string, unknown> = { user_id: user.id, updated_at: new Date().toISOString() };
  if (body.mode !== undefined) {
    if (!MODES.includes(body.mode as AutonomyMode)) {
      return NextResponse.json({ error: `Unknown mode "${body.mode}".` }, { status: 400 });
    }
    patch.mode = body.mode;
  }
  if (body.dailyAutoPostCap !== undefined) {
    const n = Number(body.dailyAutoPostCap);
    if (!Number.isFinite(n) || n < 0 || n > 500) {
      return NextResponse.json({ error: "The cap has to be between 0 and 500." }, { status: 400 });
    }
    patch.daily_auto_post_cap = Math.floor(n);
  }
  if (Object.keys(patch).length === 2) {
    return NextResponse.json({ error: "Nothing to change." }, { status: 400 });
  }

  const { error } = await adminSupabase()
    .from("starreply_settings")
    .upsert(patch, { onConflict: "user_id" });
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  await adminSupabase().from("starreply_events").insert({
    user_id: user.id,
    kind: "approve",
    title: body.mode ? `Autonomy set to ${body.mode}` : "Daily ceiling changed",
    detail: body.mode
      ? "A 2★ review or lower is still approval-only, in every mode."
      : `Now ${patch.daily_auto_post_cap} unattended replies per location per day.`,
  });

  return NextResponse.json({ ok: true });
}
/* What the console actually renders for THIS signed-in account.
 *
 * ⛔ RULE 2. Several products in this estate hand any non-demo session a hardcoded empty book, so
 * rows that exist in the database never reach a screen and a task written against them cannot be
 * a browser task. This is the measurement rather than a reading of the code: it restores the
 * captured session, opens `/`, and prints the queue rows, the controls on the open card and the
 * bar the page drew.
 *
 *   node harness/look.mjs [view]        # writes harness/look-<view>.png
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import puppeteer from "puppeteer-core";
import { launchSafe } from "./safe-chrome.mjs";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const APP = process.env.DESK_APP_URL || "http://127.0.0.1:3752";
const view = process.argv[2] || "";

const session = JSON.parse(fs.readFileSync(path.join(HERE, "session.json"), "utf8"));

const browser = await launchSafe(puppeteer, { headless: true });
try {
  await browser.setCookie(...session.cookies);
  const page = await browser.newPage();
  await page.setViewport({ width: 1440, height: 1600 });
  await page.goto(`${APP}/${view}`, { waitUntil: "networkidle2", timeout: 60000 });
  await new Promise((r) => setTimeout(r, 1200));

  const seen = await page.evaluate(() => {
    const text = (el) => (el?.textContent || "").replace(/\s+/g, " ").trim();
    return {
      title: document.title,
      rows: [...document.querySelectorAll(".fxR")].map((el) => text(el).slice(0, 140)),
      openCard: text(document.querySelector(".fxX")).slice(0, 700),
      controls: [...document.querySelectorAll("button, a.ghost, a.cta")]
        .map((b) => text(b))
        .filter(Boolean)
        .slice(0, 40),
      bodyHead: text(document.body).slice(0, 900),
    };
  });
  console.log(JSON.stringify(seen, null, 2));
  const shot = path.join(HERE, `look-${view.replace(/\W+/g, "") || "queue"}.png`);
  await page.screenshot({ path: shot, fullPage: false });
  console.log(`\nshot -> ${path.relative(process.cwd(), shot)}`);
} finally {
  await browser.close();
}

